def balanced(s):
    if not isinstance(s,str): return False
    stack=[]; pairs={')':'(',']':'[','}':'{'}
    for c in s:
        if c in '([{': stack.append(c)
        elif c in pairs:
            if not stack or stack.pop()!=pairs[c]: return False
    return not stack
assert balanced('x([{}])')
for bad in ('(]','(',']',None):
    assert not balanced(bad)
